import re

def cmp_semver(a, b):
    def parse(version):
        # Remove build metadata
        main_part = version.split('+')[0]
        # Split into main version and pre-release
        parts = main_part.split('-')
        main_version_str = parts[0]
        pre_release_str = parts[1] if len(parts) > 1 else None

        # Parse major.minor.patch
        main_nums = [int(x) for x in main_version_str.split('.')]

        # Parse pre-release identifiers
        pre_release_ids = []
        if pre_release_str:
            for part in pre_release_str.split('.'):
                if part.isdigit():
                    pre_release_ids.append((0, int(part))) # Type 0 for numeric
                else:
                    pre_release_ids.append((1, part))          # Type 1 for alphanumeric

        return main_nums, pre_release_ids

    v1_main, v1_pre = parse(a)
    v2_main, v2_pre = parse(b)

    # Compare major.minor.patch
    if v1_main != v2_main:
        return 1 if v1_main > v2_main else -1

    # Pre-release logic: 
    # A version WITH a pre-release sorts BEFORE the same version WITHOUT one.
    if v1_pre is not None and v2_pre is None:
        return -1
    if v1_pre is None and v2_pre is not None:
        return 1
    if v1_pre is None and v2_pre is None:
        return 0

    # Both have pre-releases, compare them left to right
    for i in range(max(len(v1_pre), len(v2_pre))):
        if i >= len(v1_pre):
            return -1
        if i >= len(v2_pre):
            return 1

        id1, id2 = v1_pre[i], v2_pre[i]

        # Numeric vs Alphanumeric: Numeric (type 0) sorts before Alphanumeric (type 1)
        if id1[0] != id2[0]:
            return -1 if id1[0] < id2[0] else 1

        # Same type: compare values
        if id1[1] != id2[1]:
            return -1 if id1[1] < id2[1] else 1

    return 0
