import re

def parse_range(header, size):
    if not header or 'bytes=' not in header:
        return None

    try:
        # Extract the part after 'bytes=' and split by commas
        parts = header.split('bytes=')[1].split(',')
        ranges = []

        for part in parts:
            part = part.strip()
            if not part:
                continue

            # Handle suffix range (e.g., -500)
            if part.startswith('-'):
                suffix_len = int(part[1:])
                start = max(0, size - suffix_len)
                end = size - 1
                if start < size:
                    ranges.append((start, end))
                else:
                    # If -500 is larger than size, it covers 0 to size-1
                    ranges.append((0, size - 1))
            else:
                # Handle standard range (e.g., 0-499, 500-)
                if '-' in part:
                    sub_parts = part.split('-')
                    s_str = sub_parts[0].strip()
                    e_str = sub_parts[1].strip()

                    if not s_str: # Case like "-500" handled above, but just in case
                        continue

                    start = int(s_str)
                    if not e_str: # Case like "500-"
                        end = size - 1
                    else:
                        end = min(int(e_str), size - 1)

                    if start < size:
                        ranges.append((max(0, start), end))
                else:
                    # Single number case (e.g., "500")
                    start = int(part)
                    if start < size:
                        ranges.append((start, start))

        # Filter out unsatisfiable ranges (where start > end)
        valid_ranges = [r for r in ranges if r[0] <= r[1]]

        if not valid_ranges:
            return None
        return valid_ranges

    except (ValueError, IndexError):
        return None
