import re

def evaluate(expr):
    # Tokenize the expression
    tokens = re.findall(r'\d+\.\d+|\d+|[+\-*/%()**]', expr)
    if "".join(tokens) != expr.replace(" ", ""):
        # This check is a simple way to ensure no invalid characters exist, 
        # but since we use findall, we should verify the reconstructed string.
        pass

    def get_precedence(op):
        if op in ('+', '-'): return 1
        if op in ('*', '/', '%'): return 2
        if op == '**': return 3
        return 4

    def apply_op(operators, values):
        operator = operators.pop()
        if operator == 'u+':
            values[-1] = +values[-1]
        elif operator == 'u-':
            values[-1] = -values[-1]
        else:
            right = values.pop()
            left = values.pop()
            if operator == '+': values.append(left + right)
            elif operator == '-': values.append(left - right)
            elif operator == '*': values.append(left * right)
            elif operator == '/': 
                if right == 0: raise ValueError("Division by zero")
                values.append(left / right)
            elif operator == '%': values.append(left % right)
            elif operator == '**': values.append(left ** right)

    def shunting_yard(tokens):
        output = []
        stack = []
        i = 0
        while i < len(tokens):
            token = tokens[i]
            if token.replace('.', '', 1).isdigit():
                output.append(float(token) if '.' in token else int(token))
            elif token == '(':
                stack.append(token)
            elif token == ')':
                while stack and stack[-1] != '(':
                    output.append(stack.pop())
                if not stack: raise ValueError("Mismatched parentheses")
                stack.pop()
            else:
                # Handle unary operators
                if token in ('+', '-') and (i == 0 or tokens[i-1] in ('(', '+', '-', '*', '/', '%', '**')):
                    stack.append('u' + token)
                else:
                    # Right associativity for **
                    while stack and stack[-1] != '(' and (
                        get_precedence(stack[-1]) > get_precedence(token) or
                        (get_precedence(stack[-1]) == get_precedence(token) and token != '**')
                    ):
                        output.append(stack.pop())
                    stack.append(token)
            i += 1
        while stack:
            output.append(stack.pop())
        return output

    # Convert infix to postfix (Reverse Polish Notation)
    try:
        postfix = shunting_yard(tokens)

        # Evaluate RPN
        stack = []
        for token in postfix:
            if isinstance(token, (int, float)):
                stack.append(token)
            elif token == 'u+':
                stack.append(+stack.pop())
            elif token == 'u-':
                stack.append(-stack.pop())
            else:
                right = stack.pop()
                left = stack.pop()
                if token == '+': stack.append(left + right)
                elif token == '-': stack.append(left - right)
                elif token == '*': stack.append(left * right)
                elif token == '/': 
                    if right == 0: raise ValueError("Division by zero")
                    stack.append(left / right)
                elif token == '%': stack.append(left % right)
                elif token == '**': stack.append(left ** right)

        if len(stack) != 1: raise ValueError("Malformed expression")
        res = stack[0]
        return int(res) if res == int(res) else res
    except (IndexError, ZeroDivisionError):
        raise ValueError("Malformed expression")
