def subtract(base, cuts):
    # 1. Normalize base: merge overlapping/adjacent intervals and sort them
    def merge_intervals(intervals):
        if not intervals:
            return []
        sorted_ints = sorted(intervals)
        merged = []
        curr_start, curr_end = sorted_ints[0]
        for next_start, next_end in sorted_ints[1:]:
            if next_start <= curr_end:
                curr_end = max(curr_end, next_end)
            else:
                merged.append((curr_start, curr_end))
                curr_start, curr_end = next_start, next_end
        merged.append((curr_start, curr_end))
        return merged

    normalized_base = merge_intervals(base)

    # 2. Normalize cuts: merge overlapping/adjacent intervals and sort them
    normalized_cuts = merge_intervals(cuts)

    # 3. Subtract cuts from the normalized base
    result = []
    for b_start, b_end in normalized_base:
        current_start = b_start
        for c_start, c_end in normalized_cuts:
            # If cut is completely before current interval, skip
            if c_end <= current_start:
                continue
            # If cut is completely after current interval, stop checking cuts for this base
            if c_start >= b_end:
                break

            # If there is a gap between current_start and the start of the cut
            if c_start > current_start:
                result.append((current_start, c_start))

            # Move the pointer to the end of the cut (but don't go past b_end)
            current_start = max(current_start, c_end)

        if current_start < b_end:
            result.append((current_start, b_end))

    # 4. Final pass to merge adjacent results (e.g., [1, 2) and [2, 3) -> [1, 3))
    if not result:
        return []

    final_merge = []
    last_start, last_end = result[0]
    for i in range(1, len(result)):
        next_start, next_end = result[i]
        if next_start <= last_end:
            last_end = max(last_end, next_end)
        else:
            final_merge.append((last_start, last_end))
            last_start, last_end = next_start, next_end
    final_merge.append((last_start, last_end))

    return final_merge
