function pLimit(n) {
  const queue = [];
  let activeCount = 0;

  return function (fn) {
    return new Promise((resolve, reject) => {
      queue.push({ fn, resolve, reject });
      next();
    });
  };

  function next() {
    if (activeCount >= n || queue.length === 0) {
      return;
    }

    activeCount++;
    const { fn, resolve, reject } = queue.shift();

    fn()
      .then(resolve)
      .catch(reject)
      .finally(() => {
        activeCount--;
        next();
      });
  }
}

module.exports = pLimit;
