  const trailing = !isNaN(options.trailing) ? !!options.trailing : true;

  function invoke() {
    const args = lastArgs;
    const context = lastContext;
    lastArgs = null;
    lastContext = null;
    result = fn.apply(context, args);
    return result;
  }

  const debounced = function(...args) {
    const now = Date.now();
    lastArgs = args;
    lastContext = this;
    lastCallTime = now;

    const isFirstCall = !timeoutId;
    const shouldFireLeading = leading && isFirstCall;

    if (timeoutId) {
      clearTimeout(timeoutId);
    }

    if (shouldFireLeading) {
      result = invoke();
    }

    timeoutId = setTimeout(() => {
      const shouldFireTrailing = trailing && (lastArgs !== null);
      if (shouldFireTrailing) {
        result = invoke();
      } else {
        timeoutId = null;
      }
    }, wait);

