    }
    const list = this.listeners.get(event);
    list.push({ fn, once: false });

    return () => this.off(event, fn);
  }

  once(event, fn) {
    return this.on(event, fn, true);
  }

  // Overloaded internal logic to handle 'once' flag
  _addListener(event, fn, isOnce) {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, []);
    }
    const list = this.listeners.get(event);
    list.push({ fn, once: isOnce });
    return () => this.off(event, fn);
  }

  // Re-implementing on/once to use the shared logic correctly
  on(event, fn) {
    return this._addListener(event, fn, false);
  }

  once(event, fn) {
    return this._addListener(event, fn, true);
  }

  off(event, fn) {
    const list = this.listeners.get(event);
    if (!list) return;
    const index = list.findIndex(l => l.fn === fn);
    if (index !== -1) {
      list.splice(index, 1);
    }
  }

  emit(event, ...args) {
    const list = this.listeners.get(event);
    if (!list) return 0;

    let count = 0;
    const queue = [...list];
    let firstError = null;

    for (let i = 0; i < queue.length; i++) {
      const { fn, once } = queue[i];

      try {
        fn(...args);
        count++;
        if (once) {
          const currentList = this.listeners.get(event);
          const idx = currentList.findIndex(l => l.fn === fn);
          if (idx !== -1) currentList.splice(idx, 1);
        }
      } catch (err) {
        if (!firstError) firstError = err;
      }
    }

    if (firstError) throw firstError;
    return count;
  }
