      if (typeof arg === 'object' && arg !== null) {
        if (cacheWeakMap.has(arg)) {
          return cacheWeakMap.get(arg);
        }
        try {
          const result = fn(...args);
          cacheWeakMap.set(arg, result);
          return result;
        } catch (e) {
          throw e;
        }
      } else {
        if (cacheMap.has(arg)) {
          return cacheMap.get(arg);
        }
        try {
          const result = fn(...args);
          cacheMap.set(arg, result);
          return result;
        } catch (e) {
          throw e;
        }
      }
    } else {
      // Default behavior for multiple arguments or no arguments without keyFn
      calls++;
      return fn(...args);
