export type DeepPartial<T> = {
  [P in keyof T]?: T[P] extends (infer U)[]
    ? DeepPartial<U>[]
    : T[P] extends object
    ? DeepPartial<T[P]>
    : T[P];
};

export function applyPatch<T>(base: T, patch: DeepPartial<T>): T {
  if (patch === null || typeof patch !== 'object') {
    return patch as unknown as T;
  }

  const result = Array.isArray(base) ? [...base] : { ...base };

  for (const key in patch) {
    if (!Object.prototype.hasOwnProperty.call(patch, key)) continue;

    const patchValue = patch[key];

    if (patchValue === undefined) {
      continue;
    }

    const baseValue = (base as any)[key];

    if (Array.isArray(patchValue)) {
      // Replace arrays wholesale
      (result as any)[key] = patchValue;
    } else if (patchValue !== null && typeof patchValue === 'object' && baseValue !== null && typeof baseValue === 'object' && !Array.isArray(baseValue)) {
      // Recursive merge for objects
      (result as any)[key] = applyPatch((baseValue as any), patchValue as DeepPartial<(baseValue as any)>);
    } else {
      // Primitive replacement or direct assignment
      (result as any)[key] = patchValue;
    }
  }

  return result as T;
}
